modernize-use-override.exampleBefore:
class Derived : public Base {
  void doSomething() const;
};

modernize-use-override.exampleAfter:
class Derived : public Base {
  void doSomething() const override;
};

performance-unnecessary-value-param.exampleAfter:
void printName(const std::string& name) {
  std::cout << name;
}

bugprone-use-after-move.exampleBefore:
std::string a = "Hello";
std::string b = std::move(a);
std::cout << a; // Error: 'a' is empty or invalid

bugprone-use-after-move.exampleAfter:
std::string a = "Hello";
std::string b = std::move(a);
// Do not use 'a' anymore

performance-for-range-copy.exampleAfter:
for (const auto& str : string_list) {
  std::cout << str;
}

readability-identifier-naming.exampleBefore:
class my_class {
  int SomeValue;
  void do_work();
};

readability-identifier-naming.exampleAfter:
class MyClass {
  int someValue;
  void doWork();
};
